# Terraform Module for S3, RDS, and IAM

Below is a production-ready Terraform module structure implementing the canonical scenario with dev/prod environments via `.tfvars` files.

## Directory Structure

```
terraform/
├── modules/
│   ├── s3/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   ├── outputs.tf
│   │   └── versions.tf
│   ├── rds/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   ├── outputs.tf
│   │   └── versions.tf
│   └── iam/
│       ├── main.tf
│       ├── variables.tf
│       ├── outputs.tf
│       └── versions.tf
├── environments/
│   ├── dev.tfvars
│   ├── prod.tfvars
│   └── common.tfvars
├── main.tf
├── variables.tf
├── outputs.tf
├── versions.tf
└── .gitignore
```

## Root Configuration

### `versions.tf`

```hcl
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Environment = var.environment
      Project     = var.project_name
      ManagedBy   = "Terraform"
      Owner       = var.owner_email
    }
  }
}
```

### `variables.tf`

```hcl
variable "aws_region" {
  type        = string
  description = "AWS region for deployment"
}

variable "environment" {
  type        = string
  description = "Environment name (dev/prod)"
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Environment must be dev or prod."
  }
}

variable "project_name" {
  type        = string
  description = "Project name for resource naming"
}

variable "owner_email" {
  type        = string
  description = "Owner email for resource tags"
  default     = "albert.a.artigues@gmail.com"
}

# S3 Configuration
variable "s3_bucket_prefix" {
  type        = string
  description = "Prefix for S3 bucket name"
}

variable "s3_enable_replication" {
  type        = bool
  description = "Enable cross-region replication"
  default     = false
}

variable "s3_replica_region" {
  type        = string
  description = "Replica region for S3 replication"
  default     = "us-west-2"
}

# RDS Configuration
variable "rds_instance_class" {
  type        = string
  description = "RDS instance class"
}

variable "rds_allocated_storage" {
  type        = number
  description = "Allocated storage in GB"
  default     = 20
}

variable "rds_multi_az" {
  type        = bool
  description = "Enable Multi-AZ deployment"
  default     = false
}

variable "rds_db_name" {
  type        = string
  description = "Initial database name"
  default     = "appdb"
}

variable "rds_master_username" {
  type        = string
  description = "Master username for RDS"
  default     = "admin"
  sensitive   = true
}

variable "rds_backup_retention_days" {
  type        = number
  description = "Backup retention period in days"
  default     = 7
}

# IAM Configuration
variable "iam_role_name" {
  type        = string
  description = "IAM role name for service account"
}

variable "iam_enable_oidc" {
  type        = bool
  description = "Enable OIDC provider trust (prod only)"
  default     = false
}

variable "oidc_provider_arn" {
  type        = string
  description = "OIDC provider ARN for service account federation"
  default     = ""
}

variable "oidc_service_account_namespace" {
  type        = string
  description = "Kubernetes namespace for service account"
  default     = "default"
}

variable "vpc_id" {
  type        = string
  description = "VPC ID for RDS security group"
}

variable "db_subnet_group_name" {
  type        = string
  description = "RDS DB subnet group name"
}
```

### `main.tf`

```hcl
# S3 Module
module "s3" {
  source = "./modules/s3"

  environment          = var.environment
  bucket_prefix        = var.s3_bucket_prefix
  project_name         = var.project_name
  enable_replication   = var.s3_enable_replication
  replica_region       = var.s3_replica_region
}

# RDS Module
module "rds" {
  source = "./modules/rds"

  environment           = var.environment
  instance_class        = var.rds_instance_class
  allocated_storage     = var.rds_allocated_storage
  multi_az              = var.rds_multi_az
  db_name               = var.rds_db_name
  master_username       = var.rds_master_username
  backup_retention_days = var.rds_backup_retention_days
  project_name          = var.project_name
  vpc_id                = var.vpc_id
  db_subnet_group_name  = var.db_subnet_group_name
}

# IAM Module
module "iam" {
  source = "./modules/iam"

  environment                      = var.environment
  role_name                        = var.iam_role_name
  s3_bucket_arn                    = module.s3.bucket_arn
  rds_database_arn                 = module.rds.db_instance_arn
  enable_oidc                      = var.iam_enable_oidc
  oidc_provider_arn                = var.oidc_provider_arn
  oidc_service_account_namespace   = var.oidc_service_account_namespace
  project_name                     = var.project_name
}

# Store RDS password in Secrets Manager (encrypted at rest)
resource "aws_secretsmanager_secret" "rds_password" {
  name_prefix             = "${var.project_name}-${var.environment}-rds-password-"
  description             = "RDS master password for ${var.environment}"
  recovery_window_in_days = 7

  tags = {
    Name = "${var.project_name}-rds-password"
  }
}

resource "aws_secretsmanager_secret_version" "rds_password" {
  secret_id = aws_secretsmanager_secret.rds_password.id
  secret_string = jsonencode({
    username = var.rds_master_username
    password = module.rds.db_instance_master_password
    engine   = "postgresql"
    host     = module.rds.db_instance_address
    port     = module.rds.db_instance_port
    dbname   = var.rds_db_name
  })
}
```

### `outputs.tf`

```hcl
output "s3_bucket_name" {
  value       = module.s3.bucket_name
  description = "S3 bucket name"
}

output "s3_bucket_arn" {
  value       = module.s3.bucket_arn
  description = "S3 bucket ARN"
}

output "rds_endpoint" {
  value       = module.rds.db_instance_endpoint
  description = "RDS instance endpoint"
}

output "rds_instance_id" {
  value       = module.rds.db_instance_id
  description = "RDS instance identifier"
}

output "iam_role_arn" {
  value       = module.iam.role_arn
  description = "IAM role ARN for service account"
}

output "iam_role_name" {
  value       = module.iam.role_name
  description = "IAM role name"
}

output "secrets_manager_secret_arn" {
  value       = aws_secretsmanager_secret.rds_password.arn
  description = "Secrets Manager secret containing RDS credentials"
  sensitive   = true
}
```

### `.gitignore`

```
# Local .terraform directories
**/.terraform/*

# .tfstate files
*.tfstate
*.tfstate.*

# Crash log files
crash.log

# Exclude all .tfvars files, which may contain sensitive data
*.tfvars
*.tfvars.json

# Ignore override files
override.tf
override.tf.json
*_override.tf
*_override.tf.json

# Ignore CLI configuration files
.terraformrc
terraform.rc

# IDE
.idea/
*.swp
*.swo
.DS_Store
```

## S3 Module

### `modules/s3/main.tf`

```hcl
# Generate unique bucket name
resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
  lower   = true
}

resource "aws_s3_bucket" "this" {
  bucket = "${var.bucket_prefix}-${var.environment}-${random_string.bucket_suffix.result}"

  tags = {
    Name = "${var.bucket_prefix}-${var.environment}"
  }
}

# Block all public access
resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Enable versioning
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = "Enabled"
  }
}

# Server-side encryption
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# Enable logging
resource "aws_s3_bucket_logging" "this" {
  bucket = aws_s3_bucket.this.id

  target_bucket = aws_s3_bucket_logging.this.id
  target_prefix = "logs/"
}

# Cross-region replication (for prod only)
resource "aws_s3_bucket_replication_configuration" "this" {
  count = var.enable_replication ? 1 : 0

  depends_on = [aws_s3_bucket_versioning.this]

  bucket = aws_s3_bucket.this.id

  role = aws_iam_role.replication[0].arn

  rule {
    id     = "replicate-all"
    status = "Enabled"

    filter {
      prefix = ""
    }

    destination {
      bucket       = "arn:aws:s3:::${var.bucket_prefix}-${var.environment}-replica-${random_string.bucket_suffix.result}"
      replication_time {
        status = "Enabled"
        time {
          minutes = 15
        }
      }
      metrics {
        status = "Enabled"
        event_threshold {
          minutes = 15
        }
      }
    }
  }
}

# Replica bucket (for prod only)
resource "aws_s3_bucket" "replica" {
  count = var.enable_replication ? 1 : 0

  provider = aws.replica
  bucket   = "${var.bucket_prefix}-${var.environment}-replica-${random_string.bucket_suffix.result}"

  tags = {
    Name = "${var.bucket_prefix}-${var.environment}-replica"
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  count = var.enable_replication ? 1 : 0

  provider = aws.replica
  bucket   = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

# IAM role for replication
resource "aws_iam_role" "replication" {
  count = var.enable_replication ? 1 : 0

  name_prefix = "${var.project_name}-s3-replication-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "s3.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "replication" {
  count = var.enable_replication ? 1 : 0

  name_prefix = "${var.project_name}-s3-replication-"
  role        = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.this.arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl"
        ]
        Resource = "${aws_s3_bucket.this.arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete"
        ]
        Resource = "arn:aws:s3:::${var.bucket_prefix}-${var.environment}-replica-${random_string.bucket_suffix.result}/*"
      }
    ]
  })
}
```

### `modules/s3/variables.tf`

```hcl
variable "environment" {
  type        = string
  description = "Environment name"
}

variable "bucket_prefix" {
  type        = string
  description = "Prefix for bucket name"
}

variable "project_name" {
  type        = string
  description = "Project name"
}

variable "enable_replication" {
  type        = bool
  description = "Enable cross-region replication"
  default     = false
}

variable "replica_region" {
  type        = string
  description = "Replica region"
  default     = "us-west-2"
}
```

### `modules/s3/outputs.tf`

```hcl
output "bucket_name" {
  value       = aws_s3_bucket.this.id
  description = "S3 bucket name"
}

output "bucket_arn" {
  value       = aws_s3_bucket.this.arn
  description = "S3 bucket ARN"
}

output "bucket_region" {
  value       = aws_s3_bucket.this.region
  description = "S3 bucket region"
}

output "replica_bucket_name" {
  value       = try(aws_s3_bucket.replica[0].id, "")
  description = "Replica S3 bucket name"
}
```

### `modules/s3/versions.tf`

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}
```

## RDS Module

### `modules/rds/main.tf`

```hcl
# Generate random master password
resource "random_password" "master" {
  length  = 32
  special = true
}

# RDS instance
resource "aws_db_instance" "this" {
  identifier = "${var.project_name}-${var.environment}-db"

  engine               = "postgres"
  engine_version       = "15.4"
  instance_class       = var.instance_class
  allocated_storage    = var.allocated_storage
  storage_type         = "gp3"
  storage_encrypted    = true
  kms_key_id           = aws_kms_key.rds.arn

  db_name  = var.db_name
  username = var.master_username
  password = random_password.master.result

  # Network
  db_subnet_group_name   = var.db_subnet_group_name
  publicly_accessible    = false
  vpc_security_group_ids = [aws_security_group.rds.id]

  # Backup and maintenance
  backup_retention_period = var.backup_retention_days
  backup_window           = "03:00-04:00"
  maintenance_window      = "mon:04:00-mon:05:00"
  copy_tags_to_snapshot   = true

  # High availability
  multi_az               = var.multi_az
  deletion_protection    = true
  skip_final_snapshot    = false
  final_snapshot_identifier_prefix = "${var.project_name}-${var.environment}-final-snapshot-"

  # Enhanced monitoring
  enabled_cloudwatch_logs_exports = ["postgresql"]
  monitoring_interval             = 60
  monitoring_role_arn             = aws_iam_role.rds_monitoring.arn

  # Performance insights
  performance_insights_enabled          = true
  performance_insights_kms_key_id       = aws_kms_key.rds.arn
  performance_insights_retention_period = 7

  tags = {
    Name = "${var.project_name}-${var.environment}-db"
  }
}

# KMS key for encryption
resource "aws_kms_key" "rds" {
  description             = "KMS key for ${var.project_name} RDS encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = {
    Name = "${var.project_name}-rds-key"
  }
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${var.project_name}-${var.environment}-rds"
  target_key_id = aws_kms_key.rds.key_id
}

# Security group
resource "aws_security_group" "rds" {
  name_prefix = "${var.project_name}-rds-"
  description = "Security group for ${var.project_name} RDS instance"
  vpc_id      = var.vpc_id

  lifecycle {
    create_before_destroy = true
  }

  tags = {
    Name = "${var.project_name}-${var.environment}-rds-sg"
  }
}

# Allow inbound PostgreSQL from application security group
resource "aws_vpc_security_group_ingress_rule" "postgres" {
  security_group_id = aws_security_group.rds.id

  from_port                    = 5432
  to_port                      = 5432
  ip_protocol                  = "tcp"
  referenced_security_group_id = aws_security_group.app.id
  description                  = "PostgreSQL from application"
}

# Application security group (referenced by RDS)
resource "aws_security_group" "app" {
  name_prefix = "${var.project_name}-app-"
  description = "Security group for ${var.project_name} application"
  vpc_id      = var.vpc_id

  lifecycle {
    create_before_destroy = true
  }

  tags = {
    Name = "${var.project_name}-${var.environment}-app-sg"
  }
}

# IAM role for RDS monitoring
resource "aws_iam_role" "rds_monitoring" {
  name_prefix = "${var.project_name}-rds-monitoring-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "monitoring.rds.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_monitoring" {
  role       = aws_iam_role.rds_monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}
```

