## IAM Module

### `modules/iam/main.tf`

```hcl
# IAM role for service account
resource "aws_iam_role" "service_account" {
  name_prefix = "${var.role_name}-"
  description = "Service account role for ${var.role_name}"

  assume_role_policy = var.enable_oidc ? jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Federated = var.oidc_provider_arn
      }
      Action = "sts:AssumeRoleWithWebIdentity"
      Condition = {
        StringEquals = {
          "${replace(var.oidc_provider_arn, "/^(.*provider/)/", "")}:sub" = "system:serviceaccount:${var.oidc_service_account_namespace}:${var.role_name}"
        }
      }
    }]
  }) : jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })

  tags = {
    Name = var.role_name
  }
}

# Policy for S3 access
resource "aws_iam_role_policy" "s3_access" {
  name_prefix = "${var.role_name}-s3-"
  role        = aws_iam_role.service_account.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3BucketAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket",
          "s3:GetObjectVersion"
        ]
        Resource = [
          var.s3_bucket_arn,
          "${var.s3_bucket_arn}/*"
        ]
      }
    ]
  })
}

# Policy for RDS access (prod: least privilege, dev: broader)
resource "aws_iam_role_policy" "rds_access" {
  name_prefix = "${var.role_name}-rds-"
  role        = aws_iam_role.service_account.id

  policy = var.environment == "prod" ? jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "RDSConnect"
        Effect = "Allow"
        Action = [
          "rds-db:connect"
        ]
        Resource = "${var.rds_database_arn}/*"
      }
    ]
  }) : jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "RDSAccess"
        Effect = "Allow"
        Action = [
          "rds:DescribeDBInstances",
          "rds:DescribeDBClusters",
          "rds-db:connect"
        ]
        Resource = "*"
      }
    ]
  })
}

# Policy for Secrets Manager access
resource "aws_iam_role_policy" "secrets_access" {
  name_prefix = "${var.role_name}-secrets-"
  role        = aws_iam_role.service_account.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SecretsAccess"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resource = "arn:aws:secretsmanager:*:*:secret:${var.project_name}-${var.environment}-*"
      }
    ]
  })
}

# KMS key access for encryption/decryption
resource "aws_iam_role_policy" "kms_access" {
  name_prefix = "${var.role_name}-kms-"
  role        = aws_iam_role.service_account.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "KMSDecrypt"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = "arn:aws:kms:*:*:key/*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = [
              "*"
            ]
          }
        }
      }
    ]
  })
}

# Instance profile (for EC2-based deployments)
resource "aws_iam_instance_profile" "service_account" {
  name_prefix = "${var.role_name}-"
  role        = aws_iam_role.service_account.name
}

# IAM user for programmatic access (dev only)
resource "aws_iam_user" "programmatic" {
  count = var.environment == "dev" ? 1 : 0

  name_prefix = "${var.role_name}-"
  tags = {
    Name = "${var.role_name}-programmatic"
  }
}

resource "aws_iam_access_key" "programmatic" {
  count = var.environment == "dev" ? 1 : 0

  user = aws_iam_user.programmatic[0].name
}

resource "aws_iam_user_policy_attachment" "programmatic" {
  count = var.environment == "dev" ? 1 : 0

  user       = aws_iam_user.programmatic[0].name
  policy_arn = aws_iam_policy.service_account[0].arn
}

# Inline policy for IAM user
resource "aws_iam_policy" "service_account" {
  count = var.environment == "dev" ? 1 : 0

  name_prefix = "${var.role_name}-policy-"
  description = "Policy for ${var.role_name} service account"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3Access"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          var.s3_bucket_arn,
          "${var.s3_bucket_arn}/*"
        ]
      },
      {
        Sid    = "RDSDescribe"
        Effect = "Allow"
        Action = [
          "rds:DescribeDBInstances"
        ]
        Resource = "*"
      }
    ]
  })
}
```

